import{_ as o}from"./chunks/home-estop.pc.en.Gy0nGmtF.js";import{_ as t}from"./chunks/emo.Cly4kUfc.js";import{_ as r}from"./chunks/home-status.pc.en.CGJuUpxO.js";import{_ as a,o as n,c as i,a5 as s}from"./chunks/framework.BjM_ivYE.js";const w=JSON.parse('{"title":"Emergency Stop","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/emergency.md","filePath":"manual/gui/emergency.md","lastUpdated":1790646319000}'),l={name:"manual/gui/emergency.md"};function c(h,e,d,p,m,u){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="emergency-stop" tabindex="-1">Emergency Stop <a class="header-anchor" href="#emergency-stop" aria-label="Permalink to &quot;Emergency Stop&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Always keep the emergency stop button accessible during operation. In any situation where the robot poses a risk to people or property, press the emergency stop button immediately.</p></div><h2 id="e-stop-in-the-app" tabindex="-1">E-STOP in the app <a class="header-anchor" href="#e-stop-in-the-app" aria-label="Permalink to &quot;E-STOP in the app&quot;">​</a></h2><p><img src="'+o+'" alt="E-STOP confirmation"></p><p>The red <code>E-STOP</code> button sits at the right of the top bar on the control home. On the other screens it sits at the right of the header, whenever a robot is connected or is reconnecting after a dropped link — it still works for 8 seconds after the drop. Pressing it opens the confirmation <code>Emergency stop?</code>:</p><blockquote><p>The robot immediately stops all motion and cuts power. Reinitialization is required to resume control.</p></blockquote><p>Press <code>Stop</code> to send the emergency stop, or <code>Cancel</code> to close the dialog. There is no path that fires E-STOP without this confirmation.</p><ul><li>The app sends the emergency stop on a dedicated channel, ahead of anything already queued, and repeats it on the reliable command channel.</li><li>You do not need to own the robot first: the robot accepts E-STOP from any connected device, bypassing the ownership check. It does not take ownership — the current owner stays the same.</li><li>If the robot does not acknowledge the command, the app logs <code>E-Stop send failed — no response. Use the physical E-Stop</code>. Do not wait — use the physical button.</li></ul><h2 id="physical-emergency-stop-button" tabindex="-1">Physical emergency stop button <a class="header-anchor" href="#physical-emergency-stop-button" aria-label="Permalink to &quot;Physical emergency stop button&quot;">​</a></h2><figure><img src="'+t+'" alt="Emergency stop button on the rear of the robot"><figcaption style="text-align:center;">[ Emergency stop push button — located on the rear of the robot ]</figcaption></figure><p>When the physical <strong>emergency stop button</strong> is pressed, or the app&#39;s <code>E-STOP</code> is confirmed:</p><ul><li>All joints switch to <strong>High Damping</strong> mode.</li><li>The robot resists external motion but does <strong>not</strong> accept torque or position commands.</li><li>The robot may lose its posture and settle to the ground under gravity.</li></ul><p>High Damping mode protects both the user and the robot. The robot will not execute any motion commands until the emergency stop is cleared and the robot is re-initialized.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><ol><li><strong>Ensure safety</strong> — confirm that all people and animals are at least 2 m from the robot.</li><li><strong>Release the button</strong> — if the physical button was pressed, rotate it clockwise to unlock it.</li><li><strong>Return to initial pose</strong> — if the robot has fallen or shifted, place it in the <a href="/RBQ/manual/operation/initial-pose.html">initial pose</a> on a flat surface. Do not force the joints while the robot is in High Damping mode.</li><li><strong>Re-initialize</strong> — run the automatic start sequence or the Stand motion from the <a href="/RBQ/manual/gui/control-home.html">control home</a> and confirm the robot state in the top bar before resuming operation.</li></ol><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/manual/gui/developer-mode.html#emergency">Developer mode</a>.</p></blockquote><h2 id="another-controller-is-in-control" tabindex="-1">Another controller is in control <a class="header-anchor" href="#another-controller-is-in-control" aria-label="Permalink to &quot;Another controller is in control&quot;">​</a></h2><p>Only one client controls the robot at a time. If you are connected while another app or controller holds ownership, the app dims the whole screen after about a second and blocks every control behind the overlay <code>다른 컨트롤러가 제어 중입니다</code> (another controller is in control — this overlay is shown in Korean in both languages):</p><blockquote><p>보기 전용 — 조작하려면 제어권을 가져오세요 (상대 기기는 보기 전용이 됩니다) (View only — take control to operate; the other device becomes view-only.)</p></blockquote><p>A device that is not the owner gets no video, though the status readouts stay visible. The overlay offers:</p><ul><li><code>제어권 가져오기</code> (take control) — asks the robot to hand ownership to this device. The other device becomes view-only, and the overlay disappears once ownership is yours.</li><li><code>▶ 자동 기동</code> — after the confirmation <code>Run Auto Start?</code> → <code>Auto Start</code>, takes control and runs the automatic start sequence.</li><li><code>E-STOP</code> — after the confirmation <code>Trigger emergency stop?</code> → <code>Run E-STOP</code>, sends the emergency stop without taking control.</li></ul><p>On the control home you can also check and take ownership from the <code>Overall system status</code> popover (tap the status chip in the top bar): the <code>Ownership</code> row shows <code>Held</code> when this device is the owner and <code>Take ▸</code> when it is not.</p><p><img src="'+r+'" alt="Overall system status popover with the Ownership row"></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/RBQ/manual/safety/general-safety-warning-precautions.html">General Safety Guidelines</a></li><li><a href="/RBQ/manual/safety/emergency-stop-procedures.html">Emergency Stop Procedures (detailed)</a></li></ul>',25)])])}const k=a(l,[["render",c]]);export{w as __pageData,k as default};
